inputs = ['guc', 'ucj', 'kzdzh', 'ahhva', 'jahvw']
outputs = ['dkuc', 'ucj', 'kzdzhfc', 'xuhfcjduafxu', 'jxujduafw']

changed_pairs = [(0, 'guc', 'dkuc'), (2, 'kzdzh', 'kzdzhfc'), (3, 'ahhva', 'xuhfcjduafxu'), (4, 'jahvw', 'jxujduafw')]

print("Detailed analysis of changes:")
for idx, inp, outp in changed_pairs:
    print(f"\nPair {idx}: '{inp}' -> '{outp}'")

    # Find what changes
    if len(inp) < len(outp):
        # Insertion case
        print(f"  Length increased by {len(outp) - len(inp)}")
        # Find where insertion happens
        for i in range(len(inp)):
            if inp[i] != outp[i]:
                print(f"  Inserted character '{outp[i]}' at position {i}")
                break
        else:
            # Inserted at end
            print(f"  Inserted characters '{outp[len(inp):]}' at end")
    elif len(inp) > len(outp):
        # Deletion case
        print(f"  Length decreased by {len(inp) - len(outp)}")
        # Find where deletion happens
        for i in range(len(outp)):
            if inp[i] != outp[i]:
                print(f"  Deleted character '{inp[i]}' at position {i}")
                break
    else:
        # Same length - substitution
        print("  Same length - substitution or transposition")
        for i in range(len(inp)):
            if inp[i] != outp[i]:
                print(f"  Position {i}: '{inp[i]}' -> '{outp[i]}'")

